<div class="shop-block"><div class="shop-back" @click="changePage">返回</div><div class="shop-tabs"> <div class="shop-tab-item" name="shop" @click="selectOne('其他')" :style="getTabStyle('其他')">其他</div><div class="shop-tab-item" name="shop" @click="selectOne('精灵卡')" :style="getTabStyle('精灵卡')">精灵卡</div><div class="shop-tab-money" v-if="allMes.playerMes">余额：{{allMes.playerMes.money}}</div></div><div class="shop-content"><div class="shop-content-item" v-for="item in showList"> <el-tooltip :content="item.desc" placement="top" effect="dark"><div class="shop-one" @click="buy(item)"><div class="shop-name">{{item.name}}</div><div class="shop-num" style="margin-top: 16px;">剩余：{{item.num}}</div></div></el-tooltip></div></div></div><MyDialog v-if="dialogVisible" @close="dialogVisible = false"><template #body><div class="dialog-padding"><div class="dialog-content">{{buyItem.name}}</div><div class="dialog-content">总价格：{{buyItem.allPrice}}</div><div class="dialog-content"> <el-input-number v-model="buyItem.num" :min="1" @change="handleChange"> </el-input-number></div><div class="dialog-footer"><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" @click="sureBuy()">确认</el-button></div></div></template></MyDialog>